// === Tab: mySketch ===
p5.disableFriendlyErrors = true;

let voronoi = new Voronoi();
let sites = [];
const maxSites = 1000;
let diagram;
let boundingBox = {xl: 0, xr: 0, yt: 0, yb: 0};

let palette;

let gui;
let cnv;

let intervalId;
let angle = 0;

const siteOffsetDelta = 0.03;
let siteOffset = siteOffsetDelta;

let settings = {
	vectorRotation: -0.13,
	siteEmissionRate: 20,
	drawSites: false,
	drawCells: true,
	drawEdges: false,
		nextPalette: () => initPalette(),
	saveSnapshot: () => {
    saveCanvas(cnv, 'voronoi-spiral', 'png');
  },
	restart: () => {
		restart();	
	},
};

function initGui() {
	gui = new dat.GUI({hideable: true});
	gui.width = 300;
	gui.close();

	gui
		.add(settings, 'vectorRotation')
	  .min(-1)
	  .max(1)
		.name('Vector Rotation');

	gui
		.add(settings, 'siteEmissionRate')
	  .name('Site Emission Rate (ms)')
		.min(10)
		.max(1000)
		.step(10)
		.onChange(restartAddingSites);

	gui
		.add(settings, 'drawSites')
		.name('Draw Sites');

	gui
		.add(settings, 'drawCells')
		.name('Draw Cells');

	gui
		.add(settings, 'drawEdges')
		.name('Draw Edges');

	gui
		.add(settings, 'nextPalette')
		.name('Next Palette');

	gui
		.add(settings, 'saveSnapshot')
		.name('Save Snapshot');

	gui
		.add(settings, 'restart')
	  .name('Restart');
}

function restart() {
	angle = 0;
	siteOffset = siteOffsetDelta;
	initSites();
	restartAddingSites();
}

function setup() {
	cnv = createCanvas(windowWidth, windowHeight);
	initGui();
	updateBoundingBox();
	initPalette();
	restart();
}

function initPalette() {
  palette = new Palette(random(PALETTES));
	palette.jitter = 0.5;
  return palette;
}


function startAddingSites() {
	intervalId = window.setInterval(() => {
		addNextSite();
	}, settings.siteEmissionRate);
}

function stopAddingSites() {
	window.clearInterval(intervalId);
}

function restartAddingSites() {
	stopAddingSites();
	startAddingSites();
}

function drawBackground() {
	background(100);
}

function updateBoundingBox() {
	boundingBox = {xl: 0, xr: width, yt: 0, yb: height};
}

function nextAngle() {
	angle = (angle + 15) % 360;
	return angle;
}

function draw() {
	drawBackground();
	updateSites();
	updateDiagram();
	drawDiagram();
}

function addNextSite() {
	if (sites.length < maxSites) {
		siteOffset += siteOffsetDelta;
		const c = palette.getSmooth(siteOffset % 1);
		const site = new Particle(c);
		site.x = width/2;
		site.y = height/2;
		var angle = nextAngle();
		const force = p5.Vector.fromAngle(radians(angle));
		site.applyForce(force);
		addSite(site);
	} else {
		stopAddingSites();
	}
}

function updateSites() {
	for (let i = 0; i < sites.length; i++) {
		var site = sites[i];
		site.update();
		site.vel.rotate(radians(settings.vectorRotation));
	}
}

function initSites() {
	sites = [];
	diagram = voronoi.compute(sites, boundingBox);
}

function addSite(site) {
	sites.push(site);
}

function updateDiagram() {
	voronoi.recycle(diagram);

	let visibleSites = [];

	if (voronoi.edges.length) {
		for (let i = 0; i < diagram.edges.length; i++) {
			const e = diagram.edges[i];
			if (!e.lSite && e.rSite) return e.rSite;
			if (!e.rSite && e.lSite) return e.lSite;

			// If the sites are too close together, only return one of them.
			if (e.lSite && e.rSite) {
				if (dist(e.lSite.x, e.lSite.y, e.rSite.x, e.rSite.y) > 4) {
					visibleSites.push(e.lSite);
					visibleSites.push(e.rSite);
				} else {
					visibleSites.push(e.lSite);
				}
			}
		}
	} else {
		visibleSites = sites;
	}

	diagram = voronoi.compute(visibleSites, boundingBox);	
}

function drawDiagram() {
	if (settings.drawCells) {
		noStroke();
		for (const cell of diagram.cells) {
			fill(cell.site.color);
			beginShape();
			for (const halfedge of cell.halfedges) {
				const {x, y} = halfedge.getStartpoint();
				vertex(x, y);
			}
			endShape();
		}	
	}

	if (settings.drawEdges) {
		stroke(255);
	  strokeWeight(1);
		for (const edge of diagram.edges) {
			if (edge.lSite === null || edge.rSite === null) continue;
			line(edge.va.x, edge.va.y, edge.vb.x, edge.vb.y);
		}
	}

	if (settings.drawSites) {
		stroke(0);
		strokeWeight(1);
		for (const site of sites) {
			fill(site.color);
			circle(site.x, site.y, 10);
		}
	}
}

class Particle {

	pos = createVector(0, 0);
	vel = createVector(0, 0);
	acc = createVector(0, 0);

	maxSpeed = 4;
	color;

	get x() {
		return this.pos.x;
	}

	set x(x) {
		this.pos.x = x;
	}

	get y() {
		return this.pos.y;
	}

	set y(y) {
		this.pos.y = y;
	}

  constructor(color) {
    this.color = color;
  }

  update() {
    this.vel.add(this.acc);
    this.vel.limit(this.maxspeed);
    this.pos.add(this.vel);
		this.acc.mult(0);
  } 

  applyForce(force) {
    this.acc.add(force);
  }
}

